<?php
declare(strict_types=1);
final class TransactionService {
    public static function customerByCode(PDO $db,string $code): ?array { $st=$db->prepare('SELECT * FROM customers WHERE code=? LIMIT 1');$st->execute([strtoupper($code)]);$r=$st->fetch();return $r?:null; }
    public static function txnByRef(PDO $db,string $ref): ?array { $st=$db->prepare('SELECT t.*,c.code customer_code,c.name customer_name,c.phone customer_phone,b.bank_name,b.vpa FROM transactions t JOIN customers c ON c.id=t.customer_id JOIN bank_profiles b ON b.id=t.bank_id WHERE t.reference=?');$st->execute([$ref]);$r=$st->fetch();return $r?:null; }
    public static function newCustomerCode(PDO $db): string { $n=(int)$db->query('SELECT COUNT(*) FROM customers')->fetchColumn()+1;while(true){$code='CUST'.str_pad((string)$n,4,'0',STR_PAD_LEFT);$st=$db->prepare('SELECT 1 FROM customers WHERE code=?');$st->execute([$code]);if(!$st->fetchColumn())return $code;$n++;} }
    public static function createAttempt(PDO $db,array $c,?float $amount): array {
        $bank=BankService::active($db);if(!$bank)throw new RuntimeException('No active bank QR is configured.');[$ok,$msg]=LimitService::check($db,$c,$amount);if(!$ok)throw new RuntimeException($msg);$ref=random_reference($c['code'],$bank['code']);$intent=BankService::exactIntent($bank);
        $st=$db->prepare("INSERT INTO transactions(customer_id,bank_id,reference,status,requested_amount,intent_uri,limit_breach,limit_note,created_at,updated_at) VALUES(?,?,?,'PENDING',?,?,0,'',UTC_TIMESTAMP(),UTC_TIMESTAMP())");$st->execute([$c['id'],$bank['id'],$ref,$amount===null?null:number_format($amount,2,'.',''),$intent]);$id=(int)$db->lastInsertId();SmsService::enqueueTxn($db,$id,'PENDING');return ['id'=>$id,'reference'=>$ref,'bank'=>$bank,'intent'=>$intent];
    }
    public static function reportUtr(PDO $db,string $ref,string $utr): array {
        $utr=normalize_utr($utr);if(strlen($utr)<6)return [false,'Enter a valid UTR/RRN/transaction reference'];$t=self::txnByRef($db,$ref);if(!$t)return [false,'Transaction not found'];if($t['status']!=='PENDING')return [false,'This payment is already '.$t['status'].'; customer UTR can no longer be changed.'];if(!empty($t['customer_reported_utr']))return hash_equals($t['customer_reported_utr'],$utr)?[true,'Already saved']:[false,'A UTR is already saved. Contact Admin for correction.'];$q=$db->prepare('SELECT reference FROM transactions WHERE customer_reported_utr=? AND id<>? LIMIT 1');$q->execute([$utr,$t['id']]);if($q->fetchColumn())return [false,'This UTR/transaction reference is already linked to another payment attempt.'];$q=$db->prepare('UPDATE transactions SET customer_reported_utr=?,customer_reported_at=UTC_TIMESTAMP(),updated_at=UTC_TIMESTAMP() WHERE id=?');$q->execute([$utr,$t['id']]);return [true,'UTR saved. Status remains PENDING until reconciliation.'];
    }
    public static function query(PDO $db,?int $customerId,string $period,string $status='',?int $bankId=null,string $start='',string $end='',int $limit=1000): array {
        $where=[];$args=[];if($customerId){$where[]='t.customer_id=?';$args[]=$customerId;}if($status!==''){$where[]='t.status=?';$args[]=strtoupper($status);}if($bankId){$where[]='t.bank_id=?';$args[]=$bankId;}[$s,$e]=local_period_bounds($period,$start,$end);if($s){$where[]='t.created_at>=?';$args[]=$s;}if($e){$where[]='t.created_at<?';$args[]=$e;}$sql='SELECT t.*,c.code customer_code,c.name customer_name,c.phone customer_phone,b.bank_name,b.code bank_code FROM transactions t JOIN customers c ON c.id=t.customer_id JOIN bank_profiles b ON b.id=t.bank_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY t.id DESC LIMIT '.max(1,min(5000,$limit));$st=$db->prepare($sql);$st->execute($args);return $st->fetchAll();
    }
}
